verify:
def skill():
    return 1 + sum(4*(2*j) + 2 for j in range(1, 6))

def standard():
    a = {1: Rational(1)}
    a2 = Symbol('a2')
    a[2] = solve(Eq(a[1] + a2, a2/2 + 4 + 3), a2)[0]
    for n in range(3, 12):
        an = Symbol('an')
        a[n] = solve(Eq(sum(a[k] for k in range(1, n)) + an, an/2 + n**2 + 3), an)[0]
    for n in range(2, 12):
        assert sum(a[k] for k in range(1, n + 1)) == a[n]/2 + n**2 + 3
    return sum(a[k] for k in range(1, 12))

def unique():
    return [standard()]
